import{_ as a,o,c as t,a3 as r}from"./chunks/framework.B5WAEDB7.js";const u=JSON.parse('{"title":"Introduction","description":"","frontmatter":{"title":"Introduction"},"headers":[],"relativePath":"00.docs/045.cross-language/010.introduction.md","filePath":"00.docs/045.cross-language/010.introduction.md","lastUpdated":1786613910000}'),s={name:"00.docs/045.cross-language/010.introduction.md"};function n(c,e,i,d,l,p){return o(),t("div",null,[...e[0]||(e[0]=[r('<p>The <code>electron</code> technology itself provides <code>node.js</code> and <code>c/c++</code> (.node extension) language support. However, to enable developers using different technology stacks to utilize the electron technology, the framework provides a <code>cross module</code> to create service (child) processes in other languages, while also providing a unified API to manage these processes.</p><p>Theoretically, this module can support service programs created in any language. Currently, <code>go</code> and <code>java</code> demos are available for reference.</p><p>Since the <code>go</code> language has a relatively high compatibility (cross-platform, performance, package size, ease of use, etc.), the framework provides deep integration and more support for Go.</p><h3 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h3><h4 id="go" tabindex="-1">Go <a class="header-anchor" href="#go" aria-label="Permalink to &quot;Go&quot;">​</a></h4><p>Create a Go service</p><p>Please see the documentation: <a href="/pages/b16aa7/"><strong>Go</strong></a></p><h4 id="java" tabindex="-1">Java <a class="header-anchor" href="#java" aria-label="Permalink to &quot;Java&quot;">​</a></h4><p>Create a Java service</p><p>Please see the documentation: <a href="/pages/368cc3/"><strong>Java</strong></a></p><h3 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h3><p>More features are provided via API.</p><p>Please see the documentation: <a href="/pages/74c87a/"><strong>cross API</strong></a></p>',13)])])}const g=a(s,[["render",n]]);export{u as __pageData,g as default};
